-- =====================================================================
--  SEVENTY GOSPEL ARTISTS, COMING SOON
--  Run in Supabase → SQL Editor after supabase-store.sql. Safe to re-run.
--
--  Ten artists from each of Ghana, Kenya, Nigeria, Rwanda, South Africa,
--  Tanzania and the United States, with 664 of their releases and the
--  cover art Apple Music serves for each. Every release goes on the
--  shelf as coming soon: nothing here is for sale until the artist is
--  in and the stems are up. Approving an application with the same
--  slug attaches the artist's account to these rows.
--
--  The cover is the release's own artwork, linked from Apple's image
--  service rather than copied; `link` is the release on Apple Music.
-- =====================================================================

-- the release page, and the artist's own pages
alter table public.store_versions add column if not exists link text;
alter table public.store_creators add column if not exists apple text;

-- the public view grows the link (columns are only ever added, never moved)
create or replace view public.store_shelf as
  select v.id, v.song_id, s.slug as song_slug, s.title, s.writers,
         v.creator_slug, c.name as creator_name, c.kind as creator_kind, c.flag, c.country, c.youtube as creator_youtube,
         v.kind, v.label, v.is_original, v.lane, v.key, v.bpm, v.time_sig, v.length_seconds,
         v.year, v.album, v.feat, v.youtube, v.art_key,
         v.rent_cents, v.buy_cents, v.currency, v.status, v.sales, v.approved_at, v.created_at,
         v.link
  from public.store_versions v
  join public.store_songs s on s.id = v.song_id
  join public.store_creators c on c.slug = v.creator_slug
  where v.status in ('approved','coming_soon') and c.approved_at is not null;
grant select on public.store_shelf to anon, authenticated;

