), made as (
  insert into public.store_songs (slug, title)
  select slug, title from rel
  on conflict (slug) do update set title = excluded.title
  returning id, slug
)
insert into public.store_versions (song_id, creator_slug, label, is_original, album, year, art_key, link, status, approved_at)
select m.id, r.artist, r.label, true, r.album, r.yr, r.art, r.link, 'coming_soon',
       coalesce(r.released::timestamptz, now())
from made m join rel r on r.slug = m.slug
where not exists (select 1 from public.store_versions v where v.song_id = m.id and v.creator_slug = r.artist);

-- a re-run refreshes the art and the link of what is already there
